import json;d=json.load(open('harnesses/stages.json'))
print([k for k in d if k!='problems'])
for k in d:
  if k!='problems': print(k, json.dumps(d[k])[:1500])
ps=d['problems']
for p in (ps if isinstance(ps,list) else ps.values()):
  s=json.dumps(p)
  if any(x in s[:40] for x in ['P01','P02','P03']): print(json.dumps(p,indent=1))
" | head -400

