cd ~/cp-roles/implementation-algol-60 && python3 -c "
import json;d=json.load(open('harnesses/stages.json'))
ps=d['problems']
for p in (ps if isinstance(ps,list) else ps.values()):
  if p['problem']=='P03':
    for s in p['subproblems']:
      print(s['id'], s['unknowns'], [i['id'] for i in s['instances']], [(st['stage'],st['kind'],st['description'],[q['cap'] for q in st['queries']]) for st in s['stages']], s.get('readings'))
    print(p.get('notes'))
"; cat harnesses/algol-60/QUESTIONS.md

